/** Allow at most `max` tasks to run at the same time. */
function createGate(max) {
  // Write your solution here
  let running = 0;
  return {
    get running() { return running; },
    get queued() { return 0; },
    async run(task) {
      running++;
      const result = await task();
      running--;
      return result;
    },
  };
}

